72	static QString encodeName(const QString &name, bool allowUpper = false)
73	{
74	    QString n = name.toLower();
75	    QString legal = u"abcdefghijklmnopqrstuvwxyz1234567890"_s;
76	    if (allowUpper)
77	        legal += u"ABCDEFGHIJKLMNOPQRSTUVWXYZ"_s;
78	    int pos = 0;
79	    while (pos < n.size())
80	    {
81	        if (legal.indexOf(n[pos]) == -1)
82	            n.remove(pos, 1);
83	        else
84	            ++pos;
85	    }
