164:                         newColor = (newColor & 0x0f) | WIN_BACK_GRAY;
165:                         break;
166:                     case NIX_FORE_BLACK :
167:                         newColor = (newColor & 0xF8) | WIN_FORE_BLACK;
168:                         break;
169:                     case NIX_FORE_RED :
170:                         newColor = (newColor & 0xF8) | WIN_FORE_RED;
171:                         break;
172:                     case NIX_FORE_GREEN :
173:                         newColor = (newColor & 0xF8) | WIN_FORE_GREEN;
174:                         break;
